script:
(function () {
  'use strict';
  // Compare two to four CDs over the same time horizon.
  //   While in the CD: value = P x (1 + APY)^(months / 12)  (the APY already includes compounding).
  //   CD matures before the horizon: the maturity value earns the reinvestment APY for the
  //     remaining months:  P x (1 + APY)^(T/12) x (1 + reinvest)^((H - T)/12).
  //   CD matures after the horizon: it is cashed in early at the horizon and the early withdrawal
  //     penalty (k months of interest on the deposit, P x APY x k / 12) is subtracted. The penalty
  //     can exceed the interest earned, as many banks allow.
  //   Horizon yield = (value / P)^(12 / H) - 1.
  //   Break-even reinvestment rate for a CD that matures early: the rate x at which it would tie
  //     the best CD:  x = (best value / (P (1 + APY)^(T/12)))^(12 / (H - T)) - 1.
  //   Tax (optional): interest net of any penalty x your rate (a penalty is deductible).
  // Verified (Node scratch test, tests/cr.test.js, against hand calculations):
  //   $10,000, 60-month horizon, 3% reinvestment: 12-month CD at 4.00% -> 10,400 x 1.03^4 =
  //     $11,705.29; 60-month CD at 3.50% -> 10,000 x 1.035^5 = $11,876.86; break-even
  //     reinvestment for the 12-month CD = (11,876.86 / 10,400)^(1/4) - 1 = 3.375%.
  //   60-month CD at 4% cashed at 24 months with a 6-month penalty: 10,000 x 1.04^2 - 200 =
  //     $10,616.00.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var MAX = 4, LETTERS = 'ABCD';

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function pct(x) { return (x * 100).toFixed(3) + '%'; }

  // Value at month m (m <= H) of one CD path; penalty only at the horizon when it is broken early.
  function valueAt(P, cd, m, reinvest) {
    if (m <= cd.term) return P * Math.pow(1 + cd.apy, m / 12);
    return P * Math.pow(1 + cd.apy, cd.term / 12) * Math.pow(1 + reinvest, (m - cd.term) / 12);
  }

  function evaluate(P, cd, H, reinvest) {
    var gross = valueAt(P, cd, H, reinvest);
    var early = cd.term > H;
    var penalty = early ? P * cd.apy * cd.penalty / 12 : 0;
    var value = gross - penalty;
    return { value: value, penalty: penalty, early: early, interest: value - P,
             yield: P > 0 && value > 0 ? Math.pow(value / P, 12 / H) - 1 : NaN };
  }

  function breakEven(P, cd, H, target) {
    if (cd.term >= H) return NaN;
    var atMaturity = P * Math.pow(1 + cd.apy, cd.term / 12);
    return Math.pow(target / atMaturity, 12 / (H - cd.term)) - 1;
  }

  function clear(el) { while (el.firstChild) el.removeChild(el.firstChild); }
  function cell(tr, text, tag) {
    var td = document.createElement(tag || 'td');
    if (tag === 'th') td.setAttribute('scope', tr.parentHead ? 'col' : 'row');
    td.textContent = text;
    tr.appendChild(td);
  }

  function update() {
    var count = parseInt(document.getElementById('crCount').value, 10);
    for (var k = 1; k <= MAX; k++) document.getElementById('crCd' + k).hidden = k > count;
    var P = num('crDeposit'), H = Math.round(num('crHorizon')), reinvest = num('crReinvest') / 100, tax = num('crTax') / 100;
    var error = document.getElementById('crError');
    var msg = '';
    if ([P, H, reinvest, tax].some(isNaN)) msg = 'Fill in the deposit, horizon, reinvestment rate and tax rate.';
    else if (P <= 0) msg = 'Enter a deposit above $0.';
    else if (H < 1 || H > 120) msg = 'Enter a horizon of 1 to 120 months.';
    else if (reinvest < 0 || reinvest > 0.2) msg = 'Enter a reinvestment rate from 0 to 20%.';
    else if (tax < 0 || tax > 0.6) msg = 'Enter a tax rate from 0 to 60%.';
    var cds = [];
    for (k = 1; k <= count && !msg; k++) {
      var label = 'CD ' + LETTERS.charAt(k - 1);
      var name = document.getElementById('crName' + k).value.trim() || label;
      var term = Math.round(num('crTerm' + k)), apy = num('crApy' + k) / 100, pen = num('crPenalty' + k);
      if (isNaN(term) || term < 1 || term > 120) msg = label + ': enter a term of 1 to 120 months.';
      else if (isNaN(apy) || apy < 0 || apy > 0.2) msg = label + ': enter an APY from 0 to 20%.';
      else if (isNaN(pen) || pen < 0 || pen > 60) msg = label + ': enter a penalty of 0 to 60 months of interest.';
      else cds.push({ name: name, term: term, apy: apy, penalty: pen });
    }
    error.hidden = !msg;
    error.textContent = msg;
    var head = document.getElementById('crCompareHead'), body = document.getElementById('crCompare');
    var yHead = document.getElementById('crYearHead'), yBody = document.getElementById('crYearRows');
    if (msg) {
      ['crBest', 'crBestName', 'crSpread', 'crBestYield'].forEach(function (id) { set(id, '–'); });
      [head, body, yHead, yBody].forEach(clear);
      return;
    }
    var results = cds.map(function (cd) { return evaluate(P, cd, H, reinvest); });
    var best = 0, worst = 0;
    results.forEach(function (r, i) {
      if (r.value > results[best].value + 1e-9) best = i;
      if (r.value < results[worst].value - 1e-9) worst = i;
    });
    set('crBest', money.format(results[best].value));
    set('crBestName', cds[best].name);
    set('crSpread', money.format(results[best].value - results[worst].value));
    set('crBestYield', isNaN(results[best].yield) ? '–' : pct(results[best].yield));

    clear(head);
    var hr = document.createElement('tr');
    hr.parentHead = true;
    cell(hr, '', 'th');
    cds.forEach(function (cd) { cell(hr, cd.name, 'th'); });
    head.appendChild(hr);
    clear(body);
    function line(label, fn) {
      var tr = document.createElement('tr');
      cell(tr, label, 'th');
      cds.forEach(function (cd, i) { cell(tr, fn(cd, results[i], i)); });
      body.appendChild(tr);
    }
    line('Term', function (cd) { return cd.term + ' months'; });
    line('APY', function (cd) { return (cd.apy * 100).toFixed(2) + '%'; });
    line('At the horizon', function (cd, r) {
      return r.early ? 'Cashed in early' : cd.term === H ? 'Matures' : 'Matured at month ' + cd.term;
    });
    line('Early withdrawal penalty', function (cd, r) { return r.early ? '−' + money.format(r.penalty) : '–'; });
    line('Value at ' + H + ' months', function (cd, r) { return money.format(r.value); });
    line('Interest earned', function (cd, r) { return (r.interest < 0 ? '−' : '') + money.format(Math.abs(r.interest)); });
    line('Interest after tax', function (cd, r) {
      var net = r.interest > 0 ? r.interest * (1 - tax) : r.interest;
      return (net < 0 ? '−' : '') + money.format(Math.abs(net));
    });
    line('Yield over the horizon', function (cd, r) { return isNaN(r.yield) ? '–' : pct(r.yield); });
    line('Behind the best CD by', function (cd, r) { return money.format(results[best].value - r.value); });
    line('Reinvestment rate needed to tie the best', function (cd, r, i) {
      if (i === best) return 'Best';
      var x = breakEven(P, cd, H, results[best].value);
      return isNaN(x) ? 'Not reinvested' : x > 1 ? 'Over 100%' : pct(Math.max(x, -0.9999));
    });

    clear(yHead);
    var yh = document.createElement('tr');
    yh.parentHead = true;
    cell(yh, 'Month', 'th');
    cds.forEach(function (cd) { cell(yh, cd.name, 'th'); });
    yHead.appendChild(yh);
    clear(yBody);
    var marks = [];
    for (var m = 12; m < H; m += 12) marks.push(m);
    marks.push(H);
    marks.forEach(function (mo) {
      var tr = document.createElement('tr');
      cell(tr, String(mo), 'th');
      cds.forEach(function (cd, i) {
        var v = mo === H ? results[i].value : valueAt(P, cd, mo, reinvest);
        cell(tr, money0.format(v));
      });
      yBody.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('crForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
